"""What `pbmb init` writes and `pbmb check` reads: the bundled assets and the
bootstrap values every deployment's `.env` must hold."""

from pathlib import Path

# Copied from the repository by apps/cli/scripts/sync_assets.py.
ASSETS = Path(__file__).resolve().parent / "assets"

# Each is generated by init and goes into a database URL in compose.yml.
PASSWORDS = (
    "POSTGRES_PASSWORD",
    "MIGRATOR_PASSWORD",
    "API_RW_PASSWORD",
    "WORKER_RW_PASSWORD",
    "AUDIT_WRITER_PASSWORD",
)
# What every container needs before it can read its own database.
REQUIRED_ENV = ("PUBLIC_BASE_URL", *PASSWORDS, "AUTH_SECRET")
